// File excluded from build by automated review.// Reason: duplicate putHeight(FSSpec, float) with stale FileRead/Write/Seek prototypes; not referenced#if 0#include "mesh.h"void putHeight ( FSSpec theMeshFSSpec, float factor );int FileCopy ( FSSpec *theSrcFSSpec, FSSpec *theDestFSSpec );void FileRead ( void *theDest, long theLenght, short *theMeshFileRef );void FileSeek ( short *theFileRef, long thePos );void FileWrite ( void *theDest, long theLenght, short *theMeshFileRef );void putHeight ( FSSpec theMeshFSSpec, float factor ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef, theMapFileRef;	Str255		theNewFileName = "\p:mesh.out:mesh";	Str255		theMapFileName = "\p:Graphics.in:elevation.bmp";	OSErr		theError;	FSSpec		theMapFSSpec, theNewFSSpec, theBackupFSSpec;	char meshFolder[48] = ":mesh.out:";	unsigned char *TheMap;	int i, j, x, y;	long meshSize, meshWidth, meshHeight;	struct meshHeader theMeshHeader;	struct gridData *theGrid;	struct itemTypeData *theTypes;	struct itemListData *theItems;//----------------------------------------------------------------------------------------	// copy new file to mesh.out folder		HCreate ( 0L, 0L, theNewFileName, 'MESH', 'Myth' );	theError = FSMakeFSSpec (0L, 0L, theNewFileName, &theNewFSSpec);	FileCopy ( &theMeshFSSpec, &theNewFSSpec );	theError = FSpOpenDF ( &theNewFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), &theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	FileRead(theGrid, theMeshHeader.meshLength, &theMeshFileRef);	theError = FSMakeFSSpec (0, 0, theMapFileName, &theMapFSSpec);	theError = FSpOpenDF ( &theMapFSSpec, fsCurPerm, &theMapFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open elevation.bmp.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	TheMap = (unsigned char *) NewPtr ( meshSize );	FileSeek ( &theMapFileRef, 1078L );	FileRead(TheMap, meshSize, &theMapFileRef);	FSClose ( theMapFileRef );		for ( y = meshHeight - 1, i = 0; y >= 0; y-- )		for ( x = meshWidth - 1; x >= 0; x--, i++ )				theGrid[i].height = TheMap[x + y * meshWidth] * factor;	FileSeek ( &theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, &theMeshFileRef);	DisposePtr ( (Ptr) TheMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );}#endif